create table if not exists public.college_visits(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,college_name text not null check(char_length(college_name) between 1 and 160),visit_type text not null default 'Campus Tour' check(visit_type in ('Campus Tour','Open House','Information Session','Virtual Visit','Self-Guided','Admitted Student Event')),visit_date timestamptz,status text not null default 'Planning' check(status in ('Planning','Scheduled','Completed','Cancelled')),registration_url text not null default '',questions text not null default '',notes text not null default '',follow_up text not null default '',ratings jsonb not null default '{}'::jsonb,checklist jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create index if not exists college_visits_user_date_idx on public.college_visits(user_id,visit_date);
alter table public.college_visits enable row level security;revoke all on public.college_visits from anon;grant select,insert,update,delete on public.college_visits to authenticated;
create policy "Students manage own college visits" on public.college_visits for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
